export const Q_SOLO: Questao[] = [{"id": "art-1", "disciplina": "artes", "titulo": "Desconstrução de Padrões", "contexto": "A arte frequentemente desafia os padrões de beleza convencionais, oferecendo visões que questionam as normas estéticas tradicionais. Uma estratégia comum é apresentar representações que valorizam a diversidade de corpos e identidades, promovendo uma reflexão crítica sobre os ideais impostos pela sociedade.", "pergunta": "Qual das seguintes abordagens artísticas melhor exemplifica a desconstrução de padrões de beleza?", "instrucao": "Escolha a alternativa que completa corretamente a afirmação.", "opcoes": ["Uma exposição que apresenta corpos diversos, retratados de maneira realista e valorizadora.", "A criação de pinturas que retratam apenas modelos com características específicas e consideradas “ideais”.", "A produção de fotografias que utilizam intensamente o retoque digital para idealizar a imagem.", "Uma série de esculturas que seguem os cânones clássicos de beleza."], "correta": 0, "explicacao": "Essa abordagem valoriza a diversidade de corpos e identidades, questionando os padrões estéticos tradicionais e promovendo uma reflexão crítica sobre os ideais de beleza."}, {"id": "art-2", "disciplina": "artes", "titulo": "Movimentos artísticos do século XX", "contexto": "O século XX foi marcado por vanguardas que romperam com a representação tradicional. O Cubismo, por exemplo, propôs decompor as figuras em formas geométricas, apresentando vários pontos de vista de um mesmo objeto ao mesmo tempo.", "pergunta": "Qual artista é reconhecido como um dos fundadores do Cubismo?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Claude Monet.", "Pablo Picasso.", "Salvador Dalí.", "Andy Warhol."], "correta": 1, "explicacao": "Pablo Picasso, ao lado de Georges Braque, desenvolveu o Cubismo no início do século XX, com obras como “Les Demoiselles d’Avignon” (1907)."}, {"id": "art-3", "disciplina": "artes", "titulo": "Elementos da arte contemporânea", "contexto": "Na arte contemporânea, muitas obras deixam de ser apenas objetos para contemplação e passam a envolver o espaço e o público. Instalações e performances são exemplos de linguagens que valorizam a experiência e a participação.", "pergunta": "Qual característica é mais marcante na arte contemporânea?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["O uso exclusivo de tinta a óleo sobre tela.", "A busca pela reprodução fiel da natureza.", "A valorização do conceito e da interação com o público.", "A obediência rígida às regras acadêmicas."], "correta": 2, "explicacao": "A arte contemporânea valoriza a ideia (o conceito) por trás da obra e, muitas vezes, a participação do público, usando diferentes materiais e linguagens."}, {"id": "art-4", "disciplina": "artes", "titulo": "A Semana de Arte Moderna e suas principais características", "contexto": "Realizada em 1922, no Theatro Municipal de São Paulo, a Semana de Arte Moderna reuniu artistas que queriam renovar a arte brasileira, rompendo com modelos europeus tradicionais e valorizando a identidade nacional.", "pergunta": "Qual artista participou da Semana de Arte Moderna de 1922?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Tarsila do Amaral.", "Anita Malfatti.", "Candido Portinari.", "Romero Britto."], "correta": 1, "explicacao": "Anita Malfatti expôs obras na Semana de 1922. Tarsila do Amaral, embora seja ícone do Modernismo, estava em Paris na época e não participou do evento."}, {"id": "art-5", "disciplina": "artes", "titulo": "Arte urbana", "contexto": "O grafite surgiu como expressão das periferias de grandes cidades e hoje ocupa muros, galerias e museus. No Brasil, artistas como Os Gêmeos se tornaram referência internacional.", "pergunta": "Sobre a arte urbana, é correto afirmar que:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["é produzida apenas dentro de museus.", "utiliza o espaço público como suporte e meio de diálogo com a cidade.", "não possui valor artístico reconhecido.", "surgiu no Renascimento italiano."], "correta": 1, "explicacao": "A arte urbana usa a cidade como suporte, dialogando com quem circula pelos espaços públicos."}, {"id": "his-1", "disciplina": "historia", "titulo": "A Proclamação da República e seus desdobramentos", "contexto": "Em 15 de novembro de 1889, um movimento liderado por militares pôs fim à monarquia no Brasil. O novo regime precisou se organizar política e juridicamente nos anos seguintes.", "pergunta": "Quem foi o primeiro presidente do Brasil após a Proclamação da República?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Getúlio Vargas.", "Floriano Peixoto.", "Marechal Deodoro da Fonseca.", "Prudente de Morais."], "correta": 2, "explicacao": "Marechal Deodoro da Fonseca liderou a proclamação e assumiu como chefe do Governo Provisório, sendo depois eleito o primeiro presidente."}, {"id": "his-2", "disciplina": "historia", "titulo": "A política no Brasil da Primeira República", "contexto": "Durante a Primeira República, as elites de São Paulo e Minas Gerais se revezaram no poder federal, em um acordo que garantia seus interesses econômicos.", "pergunta": "Como ficou conhecido esse acordo político?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Política do café com leite.", "Política da boa vizinhança.", "Estado Novo.", "Diretas Já."], "correta": 0, "explicacao": "A “política do café com leite” refere-se ao revezamento entre paulistas (café) e mineiros (leite) na presidência da República."}, {"id": "his-3", "disciplina": "historia", "titulo": "O contexto econômico da República Velha", "contexto": "Entre 1889 e 1930, a economia brasileira era fortemente dependente da exportação de um produto agrícola, o que tornava o país vulnerável às oscilações do mercado internacional.", "pergunta": "Qual era o principal produto de exportação do Brasil nesse período?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Cana-de-açúcar.", "Café.", "Algodão.", "Soja."], "correta": 1, "explicacao": "O café era o principal produto de exportação, e sua crise após 1929 contribuiu para o fim da República Velha."}, {"id": "his-4", "disciplina": "historia", "titulo": "O coronelismo", "contexto": "No interior do país, grandes proprietários de terras exerciam enorme influência sobre a população local, controlando votos por meio de favores e ameaças.", "pergunta": "Como era chamada a prática de controlar o voto dos eleitores nesse contexto?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Voto de cabresto.", "Voto secreto.", "Voto feminino.", "Voto distrital."], "correta": 0, "explicacao": "O “voto de cabresto” era o controle do voto pelos coronéis, favorecido pelo fato de o voto ser aberto."}, {"id": "his-5", "disciplina": "historia", "titulo": "Revoltas na Primeira República", "contexto": "Em 1904, no Rio de Janeiro, a população se rebelou contra a vacinação obrigatória imposta pelo governo, em meio a reformas urbanas que expulsavam moradores pobres do centro.", "pergunta": "Qual foi o nome desse movimento?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Revolta da Chibata.", "Guerra de Canudos.", "Revolta da Vacina.", "Revolução Farroupilha."], "correta": 2, "explicacao": "A Revolta da Vacina (1904) foi uma reação popular à vacinação obrigatória contra a varíola, conduzida por Oswaldo Cruz."}, {"id": "mat-1", "disciplina": "matematica", "titulo": "Função do 1º grau: interpretação de gráficos", "contexto": "O gráfico de uma função do 1º grau f(x) = ax + b é sempre uma reta. O sinal do coeficiente “a” indica se a função é crescente ou decrescente.", "pergunta": "Se f(x) = −3x + 5, o gráfico dessa função é uma reta:", "instrucao": "Escolha a alternativa que completa corretamente a afirmação.", "opcoes": ["crescente, que corta o eixo y em 5.", "decrescente, que corta o eixo y em 5.", "crescente, que corta o eixo y em −3.", "decrescente, que corta o eixo y em −3."], "correta": 1, "explicacao": "Como a = −3 < 0, a função é decrescente. O coeficiente b = 5 indica que a reta corta o eixo y no ponto (0, 5)."}, {"id": "mat-2", "disciplina": "matematica", "titulo": "Cálculo do zero da função", "contexto": "O zero (ou raiz) de uma função é o valor de x para o qual f(x) = 0. Graficamente, é o ponto onde a reta corta o eixo x.", "pergunta": "Qual é o zero da função f(x) = 2x − 8?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["x = −4", "x = 2", "x = 4", "x = 8"], "correta": 2, "explicacao": "Fazendo 2x − 8 = 0, temos 2x = 8, logo x = 4."}, {"id": "mat-3", "disciplina": "matematica", "titulo": "Representação algébrica da função afim", "contexto": "Uma função afim passa pelos pontos (0, 1) e (2, 7). Com esses dois pontos é possível encontrar os coeficientes a e b da lei f(x) = ax + b.", "pergunta": "Qual é a lei de formação dessa função?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["f(x) = 3x + 1", "f(x) = x + 3", "f(x) = 7x + 1", "f(x) = 2x + 7"], "correta": 0, "explicacao": "Como f(0) = 1, temos b = 1. A taxa de variação é a = (7 − 1) / (2 − 0) = 3. Assim, f(x) = 3x + 1."}, {"id": "mat-4", "disciplina": "matematica", "titulo": "Problemas envolvendo função do 1º grau", "contexto": "Um aplicativo de transporte cobra uma taxa fixa de R$ 5,00 mais R$ 2,00 por quilômetro rodado.", "pergunta": "Quanto custará uma corrida de 12 km?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["R$ 24,00", "R$ 29,00", "R$ 34,00", "R$ 17,00"], "correta": 1, "explicacao": "O preço é dado por P(x) = 2x + 5. Para x = 12: P(12) = 24 + 5 = R$ 29,00."}, {"id": "mat-5", "disciplina": "matematica", "titulo": "Taxa de variação", "contexto": "Em uma função do 1º grau, a taxa de variação indica quanto f(x) aumenta ou diminui quando x aumenta uma unidade.", "pergunta": "Na função f(x) = 4x − 1, quando x aumenta 3 unidades, f(x):", "instrucao": "Escolha a alternativa correta.", "opcoes": ["aumenta 3 unidades.", "aumenta 4 unidades.", "aumenta 12 unidades.", "diminui 1 unidade."], "correta": 2, "explicacao": "A taxa de variação é 4. Se x aumenta 3 unidades, f(x) aumenta 4 × 3 = 12 unidades."}, {"id": "bio-1", "disciplina": "biologia", "titulo": "Organelas celulares", "contexto": "As células eucariontes possuem estruturas especializadas, chamadas organelas, que realizam funções específicas para a manutenção da vida.", "pergunta": "Qual organela é responsável pela respiração celular e produção de energia?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Ribossomo.", "Mitocôndria.", "Lisossomo.", "Complexo golgiense."], "correta": 1, "explicacao": "A mitocôndria realiza a respiração celular, produzindo ATP, a principal molécula de energia da célula."}, {"id": "bio-2", "disciplina": "biologia", "titulo": "Fotossíntese", "contexto": "Plantas, algas e algumas bactérias produzem o próprio alimento a partir da luz solar, gás carbônico e água.", "pergunta": "Qual gás é liberado como produto da fotossíntese?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Oxigênio.", "Nitrogênio.", "Gás carbônico.", "Metano."], "correta": 0, "explicacao": "Na fotossíntese, a energia luminosa é usada para produzir glicose, e o oxigênio é liberado para o ambiente."}, {"id": "bio-3", "disciplina": "biologia", "titulo": "Cadeias alimentares", "contexto": "Em um ecossistema, a energia flui dos produtores para os consumidores ao longo das cadeias alimentares.", "pergunta": "Em uma cadeia alimentar, os organismos produtores são:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["os animais herbívoros.", "os fungos e bactérias decompositores.", "os seres fotossintetizantes, como as plantas.", "os predadores de topo."], "correta": 2, "explicacao": "Os produtores são seres autotróficos, como as plantas, que produzem matéria orgânica a partir da fotossíntese."}, {"id": "bio-4", "disciplina": "biologia", "titulo": "Genética mendeliana", "contexto": "Gregor Mendel estudou a transmissão de características em ervilhas e identificou padrões de herança.", "pergunta": "No cruzamento Aa × Aa, qual a proporção esperada de indivíduos aa?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["0%", "25%", "50%", "75%"], "correta": 1, "explicacao": "O cruzamento Aa × Aa gera AA, Aa, Aa e aa: 1 em 4 é aa, ou seja, 25%."}, {"id": "bio-5", "disciplina": "biologia", "titulo": "Membrana plasmática", "contexto": "Toda célula é envolvida por uma membrana que controla a entrada e a saída de substâncias.", "pergunta": "Essa propriedade da membrana plasmática é chamada de:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["permeabilidade seletiva.", "divisão celular.", "fermentação.", "mutação."], "correta": 0, "explicacao": "A membrana plasmática tem permeabilidade seletiva: ela seleciona o que entra e o que sai da célula."}, {"id": "fis-1", "disciplina": "fisica", "titulo": "Velocidade média", "contexto": "A velocidade média relaciona a distância percorrida com o tempo gasto no percurso.", "pergunta": "Um ciclista percorre 30 km em 2 horas. Qual é sua velocidade média?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["10 km/h", "15 km/h", "30 km/h", "60 km/h"], "correta": 1, "explicacao": "v = Δs / Δt = 30 km / 2 h = 15 km/h."}, {"id": "fis-2", "disciplina": "fisica", "titulo": "Primeira Lei de Newton", "contexto": "Quando um ônibus freia bruscamente, os passageiros tendem a ser projetados para a frente.", "pergunta": "Esse fenômeno é explicado pelo princípio da:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["ação e reação.", "inércia.", "gravitação universal.", "conservação da carga."], "correta": 1, "explicacao": "Pela inércia (1ª Lei de Newton), os corpos tendem a manter seu estado de movimento, por isso os passageiros seguem para a frente."}, {"id": "fis-3", "disciplina": "fisica", "titulo": "Segunda Lei de Newton", "contexto": "A força resultante sobre um corpo é igual ao produto da sua massa pela aceleração adquirida.", "pergunta": "Qual a força necessária para acelerar um corpo de 4 kg a 3 m/s²?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["7 N", "1,3 N", "12 N", "0,75 N"], "correta": 2, "explicacao": "F = m · a = 4 kg × 3 m/s² = 12 N."}, {"id": "fis-4", "disciplina": "fisica", "titulo": "Energia cinética", "contexto": "A energia cinética está associada ao movimento de um corpo e depende da sua massa e velocidade.", "pergunta": "Se a velocidade de um corpo dobra, sua energia cinética:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["dobra.", "quadruplica.", "permanece igual.", "cai pela metade."], "correta": 1, "explicacao": "Ec = m·v²/2. Como depende do quadrado da velocidade, dobrar v multiplica a energia por 4."}, {"id": "fis-5", "disciplina": "fisica", "titulo": "Terceira Lei de Newton", "contexto": "Ao nadar, a pessoa empurra a água para trás com as mãos e os pés.", "pergunta": "O que faz o nadador se mover para a frente?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["A força peso.", "A reação da água, que empurra o nadador para a frente.", "A inércia da água.", "O atrito com o ar."], "correta": 1, "explicacao": "Pela 3ª Lei de Newton (ação e reação), a água exerce sobre o nadador uma força de mesma intensidade e sentido oposto."}, {"id": "geo-1", "disciplina": "geografia", "titulo": "Escala cartográfica", "contexto": "A escala indica a relação entre as medidas do mapa e as medidas reais do terreno.", "pergunta": "Em um mapa de escala 1:100.000, 1 cm representa:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["100 m", "1 km", "10 km", "100 km"], "correta": 1, "explicacao": "1 cm no mapa corresponde a 100.000 cm no real, que equivalem a 1 km."}, {"id": "geo-2", "disciplina": "geografia", "titulo": "Biomas brasileiros", "contexto": "O Brasil possui seis biomas continentais, com características próprias de clima, solo e vegetação.", "pergunta": "Qual bioma é caracterizado por vegetação adaptada à seca e ocorre principalmente no Nordeste?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Pampa.", "Caatinga.", "Mata Atlântica.", "Pantanal."], "correta": 1, "explicacao": "A Caatinga ocorre no semiárido nordestino e possui vegetação adaptada a longos períodos de estiagem."}, {"id": "geo-3", "disciplina": "geografia", "titulo": "Urbanização", "contexto": "O crescimento acelerado das cidades brasileiras a partir de 1950 ocorreu, em grande parte, pela migração do campo para a cidade.", "pergunta": "Como se chama esse movimento migratório?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Êxodo rural.", "Transumância.", "Migração pendular.", "Diáspora."], "correta": 0, "explicacao": "O êxodo rural é a saída da população do campo em direção às cidades."}, {"id": "geo-4", "disciplina": "geografia", "titulo": "Coordenadas geográficas", "contexto": "Paralelos e meridianos formam uma rede de linhas imaginárias que permite localizar qualquer ponto da Terra.", "pergunta": "A linha imaginária que divide a Terra em hemisférios Norte e Sul é:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["o Meridiano de Greenwich.", "o Trópico de Capricórnio.", "a Linha do Equador.", "o Círculo Polar Ártico."], "correta": 2, "explicacao": "A Linha do Equador é o paralelo 0° e divide o planeta nos hemisférios Norte e Sul."}, {"id": "geo-5", "disciplina": "geografia", "titulo": "Clima", "contexto": "O clima de uma região é influenciado por fatores como latitude, altitude, massas de ar e maritimidade.", "pergunta": "De modo geral, quanto maior a altitude:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["maior a temperatura.", "menor a temperatura.", "maior a umidade.", "não há influência na temperatura."], "correta": 1, "explicacao": "Com o aumento da altitude, o ar fica mais rarefeito e retém menos calor, reduzindo a temperatura."}, {"id": "por-1", "disciplina": "portugues", "titulo": "Figuras de linguagem", "contexto": "Na frase “O vento sussurrava segredos entre as árvores”, o autor atribui uma ação humana a um elemento da natureza.", "pergunta": "Qual figura de linguagem está presente na frase?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Metáfora.", "Hipérbole.", "Personificação.", "Ironia."], "correta": 2, "explicacao": "A personificação (ou prosopopeia) atribui características humanas a seres inanimados, como o vento que “sussurra”."}, {"id": "por-2", "disciplina": "portugues", "titulo": "Classes gramaticais", "contexto": "Na frase “Ela correu rapidamente até a escola”, cada palavra exerce uma função na oração.", "pergunta": "A palavra “rapidamente” é classificada como:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["adjetivo.", "advérbio.", "substantivo.", "verbo."], "correta": 1, "explicacao": "“Rapidamente” é um advérbio de modo, pois modifica o verbo “correu”."}, {"id": "por-3", "disciplina": "portugues", "titulo": "Interpretação de texto", "contexto": "Em textos argumentativos, o autor defende um ponto de vista e apresenta argumentos para convencer o leitor.", "pergunta": "A parte do texto em que o ponto de vista principal é apresentado chama-se:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["tese.", "rodapé.", "epígrafe.", "sinopse."], "correta": 0, "explicacao": "A tese é a ideia central defendida pelo autor em um texto argumentativo."}, {"id": "por-4", "disciplina": "portugues", "titulo": "Hipérbole", "contexto": "“Já te disse um milhão de vezes para arrumar o quarto!”", "pergunta": "O exagero presente na frase caracteriza a figura de linguagem:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["eufemismo.", "hipérbole.", "antítese.", "onomatopeia."], "correta": 1, "explicacao": "A hipérbole é o exagero intencional para enfatizar uma ideia."}, {"id": "por-5", "disciplina": "portugues", "titulo": "Concordância verbal", "contexto": "A concordância verbal estabelece a relação entre o verbo e o sujeito da oração.", "pergunta": "Qual frase está de acordo com a norma-padrão?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Fazem dois anos que me mudei.", "Houveram muitos problemas.", "Faz dois anos que me mudei.", "Haviam várias pessoas na sala."], "correta": 2, "explicacao": "O verbo “fazer” indicando tempo é impessoal e fica no singular: “Faz dois anos”."}, {"id": "ing-1", "disciplina": "ingles", "titulo": "Simple Present", "contexto": "The Simple Present is used to talk about habits and routines. In the third person singular, we usually add -s or -es to the verb.", "pergunta": "Choose the correct sentence:", "instrucao": "Choose the correct alternative.", "opcoes": ["She go to school every day.", "She goes to school every day.", "She going to school every day.", "She gone to school every day."], "correta": 1, "explicacao": "Com “she” (3ª pessoa do singular) no Simple Present, o verbo recebe -es: “goes”."}, {"id": "ing-2", "disciplina": "ingles", "titulo": "Vocabulary", "contexto": "Learning vocabulary in context helps us understand texts better.", "pergunta": "What is the meaning of “library” in Portuguese?", "instrucao": "Choose the correct alternative.", "opcoes": ["Livraria.", "Biblioteca.", "Liberdade.", "Laboratório."], "correta": 1, "explicacao": "“Library” é um falso cognato: significa “biblioteca”. “Livraria” é “bookstore”."}, {"id": "ing-3", "disciplina": "ingles", "titulo": "Reading comprehension", "contexto": "“Tom wakes up at 6 a.m., has breakfast and takes the bus to work. He gets home at 7 p.m.”", "pergunta": "How does Tom go to work?", "instrucao": "Choose the correct alternative.", "opcoes": ["By car.", "On foot.", "By bus.", "By bike."], "correta": 2, "explicacao": "O texto diz “takes the bus to work”, ou seja, ele vai de ônibus."}, {"id": "ing-4", "disciplina": "ingles", "titulo": "Verb to be", "contexto": "The verb “to be” changes according to the subject: I am, you are, he/she/it is.", "pergunta": "Complete: “They ___ my friends.”", "instrucao": "Choose the correct alternative.", "opcoes": ["is", "am", "are", "be"], "correta": 2, "explicacao": "Com “they”, o verbo to be é “are”."}, {"id": "ing-5", "disciplina": "ingles", "titulo": "Falsos cognatos", "contexto": "Some English words look like Portuguese words but have different meanings.", "pergunta": "The word “pretend” means:", "instrucao": "Choose the correct alternative.", "opcoes": ["pretender.", "fingir.", "prender.", "pertencer."], "correta": 1, "explicacao": "“Pretend” significa “fingir”. “Pretender” em inglês seria “intend”."}, {"id": "qui-1", "disciplina": "quimica", "titulo": "Tabela periódica", "contexto": "Na tabela periódica, os elementos estão organizados em ordem crescente de número atômico.", "pergunta": "O número atômico de um elemento corresponde ao número de:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["nêutrons.", "prótons.", "elétrons da camada de valência.", "isótopos."], "correta": 1, "explicacao": "O número atômico (Z) é o número de prótons no núcleo do átomo."}, {"id": "qui-2", "disciplina": "quimica", "titulo": "Ligações químicas", "contexto": "O cloreto de sódio (NaCl), o sal de cozinha, é formado pela transferência de elétrons do sódio para o cloro.", "pergunta": "Que tipo de ligação ocorre no NaCl?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Covalente.", "Metálica.", "Iônica.", "De hidrogênio."], "correta": 2, "explicacao": "Na ligação iônica há transferência de elétrons entre um metal (Na) e um ametal (Cl)."}, {"id": "qui-3", "disciplina": "quimica", "titulo": "Fórmulas químicas", "contexto": "A água é uma das substâncias mais importantes para a vida e é formada por hidrogênio e oxigênio.", "pergunta": "Qual é a fórmula química da água?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["H₂O", "CO₂", "O₂", "H₂O₂"], "correta": 0, "explicacao": "A molécula de água é formada por dois átomos de hidrogênio e um de oxigênio: H₂O."}, {"id": "qui-4", "disciplina": "quimica", "titulo": "pH", "contexto": "A escala de pH indica se uma solução é ácida, neutra ou básica, variando geralmente de 0 a 14.", "pergunta": "Uma solução com pH = 3 é classificada como:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["básica.", "neutra.", "ácida.", "salina."], "correta": 2, "explicacao": "Soluções com pH menor que 7 são ácidas."}, {"id": "qui-5", "disciplina": "quimica", "titulo": "Mudanças de estado físico", "contexto": "A matéria pode passar por mudanças de estado, como fusão, vaporização e condensação.", "pergunta": "A passagem do estado sólido para o líquido é chamada de:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["solidificação.", "fusão.", "sublimação.", "condensação."], "correta": 1, "explicacao": "Fusão é a passagem do estado sólido para o líquido, como o gelo derretendo."}, {"id": "soc-1", "disciplina": "sociologia", "titulo": "Cultura e sociedade", "contexto": "A Sociologia entende cultura como o conjunto de costumes, crenças, valores e práticas compartilhados por um grupo.", "pergunta": "O processo pelo qual o indivíduo aprende as normas e valores de sua sociedade é chamado de:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["socialização.", "globalização.", "industrialização.", "urbanização."], "correta": 0, "explicacao": "A socialização é o processo de aprendizagem das normas e valores sociais, que começa na família e continua na escola e em outros grupos."}, {"id": "soc-2", "disciplina": "sociologia", "titulo": "Etnocentrismo", "contexto": "Algumas pessoas julgam outras culturas tomando a sua própria como referência de “correto” ou “superior”.", "pergunta": "Essa atitude é chamada de:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["relativismo cultural.", "etnocentrismo.", "aculturação.", "multiculturalismo."], "correta": 1, "explicacao": "Etnocentrismo é julgar outras culturas a partir dos valores da própria, considerando-a superior."}, {"id": "soc-3", "disciplina": "sociologia", "titulo": "Desigualdade social", "contexto": "A distribuição desigual de renda, acesso à educação e oportunidades marca muitas sociedades contemporâneas.", "pergunta": "Qual indicador é usado para medir a desigualdade de renda de um país?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["IDH.", "PIB.", "Índice de Gini.", "Taxa Selic."], "correta": 2, "explicacao": "O Índice de Gini mede a concentração de renda: quanto mais próximo de 1, maior a desigualdade."}, {"id": "soc-4", "disciplina": "sociologia", "titulo": "Clássicos da Sociologia", "contexto": "Émile Durkheim, Max Weber e Karl Marx são considerados os autores clássicos da Sociologia.", "pergunta": "Qual conceito está associado a Émile Durkheim?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Fato social.", "Mais-valia.", "Ação social.", "Luta de classes."], "correta": 0, "explicacao": "Durkheim definiu o fato social como maneiras de agir, pensar e sentir exteriores e coercitivas ao indivíduo."}, {"id": "soc-5", "disciplina": "sociologia", "titulo": "Movimentos sociais", "contexto": "Movimentos sociais são ações coletivas organizadas que buscam transformações na sociedade.", "pergunta": "Qual é um exemplo de movimento social?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Uma empresa multinacional.", "O movimento estudantil.", "Um partido no poder.", "Uma bolsa de valores."], "correta": 1, "explicacao": "O movimento estudantil é uma ação coletiva organizada que reivindica mudanças, como melhorias na educação."}, {"id": "fil-1", "disciplina": "filosofia", "titulo": "Filosofia antiga", "contexto": "“Só sei que nada sei” é uma frase atribuída a um filósofo grego que dialogava nas praças de Atenas.", "pergunta": "A qual filósofo essa frase é atribuída?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Platão.", "Aristóteles.", "Sócrates.", "Tales de Mileto."], "correta": 2, "explicacao": "A frase é atribuída a Sócrates e expressa a consciência da própria ignorância como ponto de partida do conhecimento."}, {"id": "fil-2", "disciplina": "filosofia", "titulo": "Mito da caverna", "contexto": "Em uma de suas obras, Platão descreve prisioneiros que só enxergam sombras projetadas na parede de uma caverna.", "pergunta": "Essa alegoria representa principalmente:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["a passagem da ignorância ao conhecimento.", "a origem dos deuses gregos.", "a formação das cidades.", "a teoria da evolução."], "correta": 0, "explicacao": "O mito da caverna simboliza a saída das aparências (sombras) rumo ao conhecimento verdadeiro."}, {"id": "fil-3", "disciplina": "filosofia", "titulo": "Ética e moral", "contexto": "Ética e moral são conceitos relacionados, mas a Filosofia costuma diferenciá-los.", "pergunta": "A ética pode ser definida como:", "instrucao": "Escolha a alternativa correta.", "opcoes": ["um conjunto de leis do Estado.", "a reflexão filosófica sobre os valores e a conduta humana.", "uma religião específica.", "uma regra de etiqueta."], "correta": 1, "explicacao": "A ética é a reflexão crítica sobre a moral, ou seja, sobre os valores que orientam as ações humanas."}, {"id": "fil-4", "disciplina": "filosofia", "titulo": "Iluminismo", "contexto": "O Iluminismo, no século XVIII, defendia a razão como caminho para o progresso e a liberdade.", "pergunta": "Qual pensador é associado à separação dos três poderes?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["Montesquieu.", "Santo Agostinho.", "Nietzsche.", "Sartre."], "correta": 0, "explicacao": "Montesquieu, em “O Espírito das Leis”, propôs a divisão entre os poderes Executivo, Legislativo e Judiciário."}, {"id": "fil-5", "disciplina": "filosofia", "titulo": "Racionalismo", "contexto": "René Descartes buscava uma verdade indubitável a partir da dúvida metódica.", "pergunta": "Qual frase resume essa conclusão de Descartes?", "instrucao": "Escolha a alternativa correta.", "opcoes": ["“O homem é a medida de todas as coisas.”", "“Penso, logo existo.”", "“Deus está morto.”", "“Conhece-te a ti mesmo.”"], "correta": 1, "explicacao": "“Penso, logo existo” (cogito, ergo sum) é a certeza que resiste à dúvida metódica de Descartes."}]

